/* @lc app=leetcode id=1354 lang=kotlin */ class Solution { fun isPossible(target: IntArray): Boolean = if (target.size == 1) target[0] == 1 else java.util.PriorityQueue<Long>(Comparator.reverseOrder()).apply { target.forEach { offer(it.toLong()) } }.let { pq -> longArrayOf(target.sumOf { it.toLong() }, -1).let { v -> run { while (v[1] == -1L && pq.peek() > 1) pq.poll().let { max -> (v[0] - max).let { rest -> if (rest == 1L) v[1] = 1 else if (rest == 0L || max <= rest || max % rest == 0L) v[1] = 0 else (max % rest).let { newVal -> (rest + newVal).also { v[0] = it }.also { pq.offer(newVal) } } } } }.let { if (v[1] != -1L) v[1] == 1L else true } } } }